'use strict';
const {cards,stories,mission}=WORLD, keys=['move','look','engage','help','take','overpower'], skills=['移動','查看','接觸','幫助','獲取','壓制'], directions={north:'北',east:'東',south:'南',west:'西'}, faces=['空白','空白','生命','挫折','士氣','時間'], statNames=['時間','士氣','生命'], crashRows=[[761,691,770,683,694,780,787,387,385,709,301,676,667,664,680,705,316,351,773,668,305],[126,308,357,725,374,405,115,471,140,354,146,722,112,148,411,137,359,314,408,136,106],[426,476,134,631,479,734,144,433,362,456,449,751,452,364,366,368,119,428,737,755,739],[601,221,346,622,194,777,228,249,192,349,400,397,237,225,180,183,205,402,177,784,245],[613,223,610,501,267,258,203,417,423,153,123,212,270,482,414,629,419,150,172,496,163],[298,297,269,747,759,278,508,338,469,464,460,506,437,444,275,286,336,334,288,441,447]];
const slotKey='wanjing.solo.1', rng=n=>Math.floor(Math.random()*n), pad=n=>String(n).padStart(3,'0'), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), opt=(v,t)=>'<option value="'+esc(v)+'">'+esc(t)+'</option>', btn=(t,fn,primary=false)=>'<button '+(primary?'class="primary" ':'')+'onclick="'+esc(fn)+'">'+esc(t)+'</button>', select=(id,opts)=>'<select id="'+id+'">'+opts+'</select>', val=id=>document.getElementById(id).value;
let s=null;try{s=JSON.parse(localStorage.getItem(slotKey))}catch{};let available=[],tab='探險',notice='';
function save(){try{localStorage.setItem(slotKey,JSON.stringify(s))}catch{notice='此瀏覽器無法儲存進度。'}render()}
function pair(){return [rng(6),rng(6)]}
function pairKey(p){let a=keys[p[0]],b=keys[p[1]];return a+'|'+b in mission?a+'|'+b:b+'|'+a}
function start(){let hero=+val('hero'),diff=+val('diff');s={phase:'mission',hero,turn:1,stats:[diff,diff,diff],skill:Array(6).fill(0),pair:pair(),grid:Array(9).fill(0),reserve:[],supply:[],boost:{},markers:{},occupied:{},penalty:0,money:0,log:[],used:[],once:[],fates:[],full:false};s.skill[hero]++;s.grid[4]=1435+hero;s.boost[1435+hero]=2;save()}
function confirmMission(){s.mission=mission[pairKey(s.pair)];s.pair.forEach(i=>s.skill[i]++);s.phase='escape';save()}
function escapePod(){let i=+val('pod');s.pod=i;s.skill[i]++;s.pair=pair();s.phase='crash';save()}
function land(){s.pair.forEach(i=>s.skill[i]++);travel(crashRows[s.pod][Object.keys(mission).indexOf(pairKey(s.pair))]);s.phase='ready';save()}
function travel(n){s.visits??={};if(s.loc)s.visits[s.loc]=s.used;s.loc=+n;s.used=s.visits[n]??[];s.extra=false;s.log.push('抵達地點 '+pad(n))}
function art(n){if(n===1)return '<img class="art" src="books/07_016.webp" alt="地點 001" onclick="pageView(7,16)">';return '<img class="art" alt="卡牌 '+n+'" src="cards/'+Number(n)+'.webp" onclick="card('+Number(n)+')">'}
function show(html){detail.innerHTML=html;if(!viewer.open)viewer.showModal()}
function card(n){if(cards[n])show('<img onclick="this.classList.toggle(\'zoomed\')" src="cards/'+Number(n)+'.webp" alt="卡牌 '+n+'">')}
function home(){return '<div class="hero"><div><small>單人開放世界探險</small><h1>萬境奇旅</h1><p>旅者號抵達軌道。你的逃生艙將落向何方？</p></div></div><section class="panel"><h2>登上旅者號</h2><label>角色 '+select('hero',['朱爾斯','索倫','埃米利安','艾拉','愛麗兒','蒂娜'].map((n,i)=>opt(i,n+' · '+skills[i])).join(''))+'</label><label>初始屬性 '+select('diff',[4,5,6,3].map((v,i)=>opt(v,['無畏','務實','謹慎','莽撞'][i]+' · '+v)).join(''))+'</label>'+btn('開始探險','start()',true)+'</section>'}
function setup(){let p=s.phase;return '<div class="panel"><small>旅者號　／　開局</small><h2>'+({mission:'接收使命訊號',escape:'選擇逃生艙',crash:'確認墜落航線'})[p]+'</h2>'+(p==='escape'?'選擇一項技能並獲得 1 點，搭乘對應的逃生艙。'+select('pod',skills.map((v,i)=>opt(i,v)).join(''))+btn('進入逃生艙','escapePod()',true):'<p>技能骰　'+s.pair.map(i=>skills[i]).join(' ＋ ')+'</p>'+art(p==='mission'?mission[pairKey(s.pair)]:s.pod+2)+(s.pair[0]===s.pair[1]?btn('重擲這一對','s.pair=pair();save()'):'')+btn(p==='mission'?'接受使命':'降落並開始第一回合',p==='mission'?'confirmMission()':'land()',true))+'</div>'}
function pool(){return 10-s.penalty-Object.keys(s.occupied).length-(s.a?.dice?.length||0)}
function refresh(){s.occupied={};s.penalty=0}
function stat(i,d){if(d>0&&s.stats[i]===6)s.skill[rng(6)]++;else s.stats[i]=Math.max(0,Math.min(6,s.stats[i]+d))}
const compass={N:'北',S:'南',W:'西',E:'東',NE:'東北',SE:'東南',NW:'西北',SW:'西南','N/NW':'北或西北'};
const departures={};for(const [key,row] of Object.entries(stories)){if(key.startsWith('story:depart:'))(departures[row[0]]??={})[key]=row}
function actions(){let list=[];function add(id,kind){for(const a of cards[id]?.actions||[]){if(kind==='地點'&&s.used.length&&!a.repeatable&&(!s.extra||s.used.includes(a.action_uid)))continue;if(s.once.includes(a.action_uid))continue;list.push({id,kind,key:a.action_uid,name:a.action||a.family||skills[keys.indexOf(a.book)],book:a.book,event:a.event_uid})}}
add(s.loc,'地點');for(const [dir,e] of Object.entries(cards[s.loc]?.exits||{})){if(e.destination||e.event_uid)list.push({id:s.loc,kind:'離開',name:'向'+directions[dir]+'離開',book:'move',event:e.event_uid,dest:e.destination,cost:e.cost})}
for(const [event,row] of Object.entries(departures[s.loc]||{})){if(list.some(x=>x.event===event))continue;list.push({id:s.loc,kind:'離開',name:'向'+(compass[row[3]]||row[3]||'特殊出口')+'離開',book:'move',event,cost:row[2]})}
for(const id of [...s.grid,...s.supply,s.mission,...s.fates].filter(Boolean))add(id,'卡牌');return list}
function printedAction(){
 let name=val('printName').trim(),book=val('printBook'),kind=val('printKind'),id=kind==='地點'||kind==='離開'?s.loc:Number(val('printId'));
 if(!name)return warn('請輸入卡面上的行動名稱。');
 if(kind==='卡牌'&&![...s.grid,...s.supply,s.mission,...s.fates].includes(id))return warn('請選網格、供應或中央區的卡牌。');
 if(kind==='地點'&&s.used.length&&!s.extra&&!document.getElementById('repeatPrinted').checked)return warn('此地點已行動過，只有卡面明示始終可用的行動可再用。');
 let key=kind+id+name;if(kind==='地點'&&s.extra&&s.used.includes(key))return warn('繼續時請選另一個地點行動。');
 s.a={id,kind,key,name,book:kind==='離開'?'move':book,cost:null,title:name,text:'依卡面或原書中此行動的結果結算。',dice:[]};
 if(kind==='地點')s.used.push(key);s.extra=false;s.phase='cost';save()
}
function printControls(){return '<details><summary>依卡面執行其他行動</summary><p>卡面另列出口、行動或費用時可從這裡執行。</p>'+select('printKind',['地點','離開','卡牌'].map(v=>opt(v,v)).join(''))+select('printId',[...new Set([...s.grid,...s.supply,s.mission,...s.fates].filter(Boolean))].map(n=>opt(n,'卡牌 '+n)).join(''))+select('printBook',keys.map((k,i)=>opt(k,skills[i])).join(''))+'<input id="printName" placeholder="卡面行動名稱"><label><input type="checkbox" id="repeatPrinted"> 卡面註明始終可用</label>'+btn('宣告卡面行動','printedAction()')+'</details>'}
function choose(i){let a=available[i];if(!a)return;let e=stories[a.event];s.a={...a,cost:e?.[2]??a.cost??null,title:e?.[5]||a.name,text:e?.[1]||(a.dest?'前往地點 '+pad(a.dest)+'。':'依卡面說明結算。'),dice:[]};s.phase='cost';if(a.kind==='地點')s.used.push(a.key);if(/每場遊戲最多|每局.*一次/.test(s.a.title))s.once.push(a.key);s.extra=false;save()}
function roll(){let a=s.a,k=keys.indexOf(a.book);let cost=a.cost==='X'?+val('xcost'):a.cost===null?(val('printed')===''?NaN:Number(val('printed'))):Number(a.cost);a.effort=cost;if(!Number.isInteger(cost)||cost<0||cost>10)return warn('請依原書確認費用後再擲骰。');let pay=Math.min(cost,k<0?0:s.skill[k],+val('pay'));if(k>=0)s.skill[k]-=pay;let n=cost-pay;if(pool()<n)refresh();a.dice=Array.from({length:n},()=>faces[rng(6)]);s.phase=n?'dice':'result';save()}
function slots(){let a=s.a,die=a.dice[0],result={time:'時間',morale:'士氣',health:'生命',setback:'挫折'};return s.grid.filter(Boolean).flatMap(id=>cards[id].slots.filter(q=>!(q.uid in s.occupied)&&(!q.result||result[q.result]===die)&&(!q.action||q.action===skills[keys.indexOf(a.book)])&&(!q.ability||q.ability.split(/\s*\|\s*|[/／]/).some(v=>a.name.split(/[/／]/).includes(v)))&&(s.boost[id]||0)>=q.boost_cost).map(q=>({id,q})))}
function assign(i){let a=s.a,d=a.dice[0];if(i===-1){if(d!=='挫折')s.penalty++;if(statNames.includes(d))stat(statNames.indexOf(d),-1)}else{let e=slots()[i];if(!e)return;let {id,q}=e;if(['terrain_specific','element_specific'].includes(q.type)&&!confirm('請對照地點與卡牌：符合此骰槽印刷的地形或成分嗎？'))return;s.occupied[q.uid]=d;s.boost[id]=Math.min(cards[id].cap,(s.boost[id]||0)-q.boost_cost+q.boost_reward)}a.dice.shift();if(!a.dice.length)s.phase='result';save()}
function finish(extra=false){let a=s.a;if(a.dest)travel(a.dest);s.log.push(a.name+' · '+a.title);s.extra=extra&&a.kind==='地點'&&a.id===s.loc;s.turn+=extra?0:1;s.pendingCard=null;s.a=null;s.phase='ready';save()}
function mainTurn(){let a=s.a;if(s.phase==='ready'){available=actions();return '<h2>選擇行動</h2>'+(s.loc===1?btn('選擇逃生艙','s.phase="escape";save()'):'')+['地點','離開','卡牌'].map(g=>'<h3>'+g+'</h3><div class="actions">'+available.map((a,i)=>a.kind===g?btn((g==='卡牌'?a.id+' · ':'')+a.name,'choose('+i+')'):'').join('')+'</div>').join('')+printControls()}
if(s.phase==='cost')return '<h2>'+esc(a.title)+'</h2><p>'+skills[keys.indexOf(a.book)]+'費用　'+(a.cost===null?'請核對原書':esc(a.cost))+'</p>'+sourceButton(a)+(a.cost===null?select('printed',opt('','選擇印刷費用')+Array.from({length:11},(_,i)=>opt(i,i)).join('')):'')+(a.cost==='X'?select('xcost',[1,2,3,4,5,6].map(i=>opt(i,i)).join('')):'')+'支付匹配技能 '+select('pay',Array.from({length:(s.skill[keys.indexOf(a.book)]||0)+1},(_,i)=>opt(i,i)).join(''))+btn('確認費用並擲骰','roll()',true);
if(s.phase==='dice')return '<h2>放置挑戰骰</h2><p class="dice">'+a.dice.map((d,i)=>btn((i===0?'▸ ':'')+d,'pickDie('+i+')')).join('')+'</p><p>目前處理「'+a.dice[0]+'」。依卡面檢查地形、成分和額外條件。</p>'+slots().map(({id,q},i)=>btn(id+' · '+(q.action||q.ability||q.result||'依卡面限制')+' 骰槽','assign('+i+')')).join('')+btn('支付 1 角色強化重擲','heroReroll()')+btn('依其他卡牌效果重擲這顆骰','rerollDie()')+btn('承受此骰結果','assign(-1)',true);
return resultPanel(a)}
function pickDie(i){let dice=s.a.dice;dice.unshift(...dice.splice(i,1));save()}
function heroReroll(){let id=s.grid[4];if(!(s.boost[id]>=1))return warn('角色需要 1 點強化。');s.boost[id]--;let before=s.a.dice[0];s.a.dice[0]=faces[rng(6)];let same=before===s.a.dice[0];if(same)s.skill[s.hero]++;notice=before+' → '+s.a.dice[0]+(same?'，獲得 1 點'+skills[s.hero]:'');save()}
function rerollDie(){let dice=s.a.dice,old=dice[0];dice[0]=faces[rng(6)];notice='重擲：'+old+' → '+dice[0]+'。請依卡牌支付強化並結算。';save()}
function resultPanel(a){
 let parts=a.text.split(/(?=[·•])/),branch=parts.length>1&&/選擇一項|選擇其中|選擇以下/.test(parts[0]);
 let shown=branch?parts[0]+(a.choice!=null?' '+parts[a.choice]:''):a.text;
 let options=branch&&a.choice==null?parts.slice(1).map((p,i)=>btn('選項 '+(i+1)+' · '+p.slice(1).split(/[：:；。]/)[0],'s.a.choice='+(i+1)+';save()')).join(''):'';
 let continuation=/繼續(?:[。！；，]|$)|繼續執行/.test(shown),required=continuation&&!/可以|如果|可選/.test(shown);
 return '<h2>'+esc(a.title)+'</h2>'+(a.cost==='X'?'<p>投入費用 '+a.effort+'</p>':'')+'<p class="story">'+esc(shown)+'</p>'+sourceButton(a)+options+
 (branch&&a.choice==null?'':effectsView(shown)+(/交鋒|卡牌798|卡牌和骰子游戲/.test(shown)&&!a.duelDone?btn('進入交鋒快速對決','beginDuel()'):'')+btn('開啟行囊',"go('行囊')")+(required?'':btn('結束行動','finish()',true))+(continuation?btn('繼續行動','finish(true)',required):''))
}
function sourceButton(a){let book=a.event?.split(':')[1]||a.book;let page=bookIndex[book+':'+a.id];if(!page)return '';return btn('查看原書 · 第 '+page[1]+' 頁','pageView('+page[0]+','+page[1]+')')}
function listedEffects(t){
 let effects=[];
 for(const m of t.matchAll(/(獲得|失去|支付)([1-9])點?(隨機技能|移動|查看|接觸|幫助|獲取|壓制|強化|錢幣|生命|士氣|時間)/g))effects.push({label:m[0],kind:m[3],delta:(m[1]==='獲得'?1:-1)*Number(m[2]),paid:m[1]==='支付'});
 for(const m of t.matchAll(/(?:前往|移動至|抵達)[^。，；·0-9]{0,9}([0-9]{3})(?![0-9])/g))if((+m[1]===1||cards[+m[1]]?.home==='location')&&!s.a.dest)effects.push({label:m[0],dest:+m[1]});
 for(const m of t.matchAll(/獲得(?:一張|1張)?(?:物品|動物|植物|能力|載具|建築|課程|命運|任務|智慧生物|卡牌|經驗|同伴|盟友|裝備)[（( ]*([0-9]{3,4})/g))if(cards[+m[1]])effects.push({label:m[0],card:+m[1]});
 return effects
}
function effectsView(t){let a=s.a;a.effects=listedEffects(t);return (a.effects.length?'<p>依已滿足的條件點選效果。</p>':'')+a.effects.map((e,i)=>a.applied?.includes(i)?'<span>✓ '+esc(e.label)+'</span>':btn(e.label,'applyEffect('+i+')')).join('')+'<p class="note">取得卡牌、替換或特殊效果可在行囊依條目登記。</p>'}
function applyEffect(i){let a=s.a,e=a.effects[i];if(!e||a.applied?.includes(i))return;let k=skills.indexOf(e.kind),v=statNames.indexOf(e.kind),id=a.kind==='卡牌'?a.id:s.grid[4];
 let balance=k>=0?s.skill[k]:v>=0?s.stats[v]:e.kind==='強化'?s.boost[id]||0:s.money;
 if(e.card){s.pendingCard={n:e.card,index:i};tab='行囊';return save()}if(e.paid&&balance < -e.delta)return warn('支付所需資源不足。');
 if(e.dest)travel(e.dest);else if(k>=0)s.skill[k]=Math.max(0,s.skill[k]+e.delta);else if(v>=0){for(let j=0;j<Math.abs(e.delta);j++)stat(v,Math.sign(e.delta))}else if(e.kind==='強化')s.boost[id]=Math.max(0,Math.min(cards[id].cap,balance+e.delta));else if(e.kind==='錢幣')s.money=Math.max(0,balance+e.delta);else if(e.kind==='隨機技能'&&e.delta>0){for(let j=0;j<e.delta;j++)s.skill[rng(6)]++}else return warn('請依條目在行囊結算。');
 (a.applied??=[]).push(i);save()
}

function characterPower(resource){let n=s.grid[4];if((s.boost[n]||0)<2)return warn('角色需要 2 點強化。');s.boost[n]-=2;if(resource==='money')s.money++;else s.skill[s.hero]++;save()}
function selectRefresh(uid){if(uid==='penalty')s.penalty=Math.max(0,s.penalty-1);else delete s.occupied[uid];save()}
function diceManagement(){let entries=Object.entries(s.occupied);return '<details><summary>依效果刷新個別骰子</summary>'+entries.map(([uid,d])=>btn(uid.split(':')[1]+' · '+d,'selectRefresh('+JSON.stringify(uid)+')')).join('')+(s.penalty?btn('懲罰區 · 刷新 1 顆','selectRefresh("penalty")'):'')+'</details>'}
function reserveSize(){return s.reserve.filter(n=>n<1517||n>1528).length+Number(s.reserve.some(n=>n>=1517&&n<=1528))}
function setRoom(){let n=Number(val('room'));if(Number.isInteger(n)&&n>=0&&n<=99){s.room=n;save()}}
function capacityView(){let cap=s.room??1,count=reserveSize();return '<details'+(count>cap?' open':'')+'><summary>儲備容量　'+count+' / '+cap+'</summary><p>將網格與供應區的容量圖示相加。整套《交鋒》收藏只佔一格。</p><label>容量總和 <input id="room" type="number" min="0" max="99" value="'+cap+'"></label>'+btn('更新容量','setRoom()')+(count>cap?'<p>請依規則移除超出容量的卡牌。</p>':'')+'</details>'}
function bag(){return '<h2>隨身行囊</h2><div class="board">'+s.grid.map((n,i)=>'<button onclick="'+(n?'card('+n+')':'')+'">'+(n?'<img src="cards/'+n+'.webp" alt="卡牌 '+n+'">':'空位 '+(i+1))+'</button>').join('')+'</div><p>使命 '+btn(s.mission,'card('+s.mission+')')+'　命運 '+s.fates.map(n=>btn(n,'card('+n+')')).join('')+'</p><p>儲備 '+s.reserve.map(n=>btn(n,'card('+n+')')).join('')+'　供應 '+s.supply.map(n=>btn(n,'card('+n+')')).join('')+'</p>'+capacityView()+'<h3>依卡面結算</h3><label>牌號 <input id="item" type="number" min="2" max="1714" value="'+(s.pendingCard?.n||'')+'"></label>'+select('zone',[...s.grid.map((_,i)=>opt('g'+i,'網格 '+(i+1))),opt('reserve','儲備'),opt('supply','供應'),opt('fates','命運'),opt('replace','替換指定網格的卡牌'),opt('remove','失去此牌'),opt('travel','前往地點')].join(''))+select('target',s.grid.map((v,i)=>opt(i,'替換位置 '+(i+1))).join(''))+btn('登記','place()')+'<p>放置、轉移或失去卡牌時，請依卡面處理收益與儲備容量。</p>'+[...new Set([...s.grid,...s.reserve,...s.supply,s.mission,...s.fates].filter(Boolean))].map(n=>'<div>'+btn(n,'card('+n+')')+' 強化 '+(s.boost[n]||0)+'/'+cards[n].cap+btn('−','boost('+n+',-1)')+btn('＋','boost('+n+',1)')+' 標記 '+(s.markers[n]||0)+btn('−','mark('+n+',-1)')+btn('＋','mark('+n+',1)')+'</div>').join('')+diceManagement()+'<h3>角色異能</h3>'+btn('支付 2 強化換 1 錢幣','characterPower("money")')+btn('支付 2 強化換角色技能','characterPower("skill")')+'<h3>環境傷害</h3>'+btn('失去 1 生命','stat(2,-1);save()')+btn('失去 1 時間與 1 士氣','stat(0,-1);stat(1,-1);save()')+'<h3>技能與資源</h3>'+skills.map((v,i)=>'<div>'+v+'　'+s.skill[i]+btn('−','adjust("skill",'+i+',-1)')+btn('＋','adjust("skill",'+i+',1)')+'</div>').join('')+statNames.map((v,i)=>'<div>'+v+'　'+s.stats[i]+btn('−','adjust("stats",'+i+',-1)')+btn('＋','adjust("stats",'+i+',1)')+'</div>').join('')+'錢幣　'+s.money+btn('−','s.money=Math.max(0,s.money-1);save()')+btn('＋','s.money++;save()')+'<label>擲技能骰數 '+select('skillCount',Array.from({length:12},(_,i)=>opt(i+1,i+1)).join(''))+'</label>'+btn('依效果擲技能骰','skillRoll()')+btn('依效果刷新骰池','refresh();save()')}
function skillRoll(){let dice=Array.from({length:Number(val('skillCount'))},()=>skills[rng(6)]);notice='技能骰：'+dice.join('、')+'。依效果登記收益。';s.log.push(notice);save()}
function boost(n,d){s.boost[n]=Math.max(0,Math.min(cards[n].cap,(s.boost[n]||0)+d));save()}
function mark(n,d){s.markers[n]=Math.max(0,(s.markers[n]||0)+d);save()}
function adjust(k,i,d){if(k==='stats')stat(i,d);else s[k][i]=Math.max(0,s[k][i]+d);save()}
function place(){let n=+val('item'),z=val('zone');if(z==='travel'&&n===1){travel(1);return save()}if(!cards[n])return warn('請輸入有效的牌號。');if(z==='travel'){if(cards[n].home!=="location")return warn('請輸入地點牌號。');travel(n);return save()}if(['reserve',...s.grid.map((_,i)=>'g'+i)].includes(z)&&cards[n].orientation!=='portrait')return warn('橫向卡牌應放在供應區或中央區。');if(z==='replace'){let i=+val('target'),old=s.grid[i];if(!old||s.grid.includes(n)||cards[n].orientation!=='portrait')return warn('請選有牌的位置與新的豎向卡。');if(i===4&&n!==1447+s.hero)return warn('請依角色的對應動力裝甲編號替換。');for(const q of cards[old].slots)delete s.occupied[q.uid];s.boost[n]=Math.min(cards[n].cap,i===4?s.boost[old]||0:cards[n].initial);delete s.boost[old];delete s.markers[old];s.reserve=s.reserve.filter(x=>x!==n);s.grid[i]=n;return save()}if(n===s.grid[4]||n===s.mission)return warn('保留角色與當前使命。');if(z[0]==='g'&&z!=='remove'){let i=+z.slice(1);if(s.grid.includes(n)){if(s.pendingCard?.n===n&&s.a){(s.a.applied??=[]).push(s.pendingCard.index);s.pendingCard=null;tab='探險'}boost(n,1);return}if(s.grid[i]&&s.reserve.includes(n)&&i!==4){let old=s.grid[i];s.reserve.push(old);for(const q of cards[old].slots)delete s.occupied[q.uid];s.grid[i]=0}if(s.grid[i])return warn('請先儲備或移走該位置的卡牌。')}
let fresh=!s.reserve.includes(n)&&!s.grid.includes(n)&&!s.supply.includes(n);if(fresh&&z[0]==='g')s.boost[n]=Math.min(cards[n].initial,cards[n].cap);for(let q of cards[n].slots)delete s.occupied[q.uid];s.grid=s.grid.map(v=>v===n?0:v);for(let q of ['reserve','supply','fates'])s[q]=s[q].filter(v=>v!==n);if(z[0]==='g')s.grid[+z.slice(1)]=n;else if(z!=='remove')s[z].push(n);else{delete s.boost[n];delete s.markers[n]}if(s.pendingCard?.n===n&&s.a&&z!=='remove'){(s.a.applied??=[]).push(s.pendingCard.index);s.pendingCard=null;tab='探險'}if(!s.full&&s.grid.every(Boolean)){s.full=true;if(!s.fates.includes(1705))s.fates.push(1705);notice='首次填滿網格，獲得命運 1705。'}save()}
function warn(t){notice=t;render()}
function records(){return '<h2>探險手冊</h2>'+ (s.duel?btn('繼續交鋒','duelView()'):'')+'<p>回合依序為宣告行動、揭示費用、支付技能、擲骰、放置、承受懲罰、閱讀結果及結束。普通地點行動每局在同一地點限一次，重訪時仍受限制。</p><div>'+select('book',['規則','壓制','幫助','接觸','查看','獲取','秘密','移動','萬境','離開'].map((v,i)=>opt(i+1,v)).join(''))+' 第 <input id="page" value="1" type="number" min="1"> 頁'+btn('翻閱','pageView()')+'</div><h3>指定條目</h3><input id="find" placeholder="牌號" type="number">'+btn('查卡','card(+val("find"))')+btn('查故事','lookup()')+'<h3>旅程紀錄</h3>'+s.log.slice(-20).reverse().map(l=>'<div>'+esc(l)+'</div>').join('')+'<hr>'+btn(s.missionDone?'使命已完成':'依使命牌確認已達成目標','s.missionDone=true;save()')+s.fates.map(n=>btn('依命運牌 '+n+' 確認已完成','s.fateDone='+n+';save()')).join('')+btn('依規則結束探險','ending()')}
function lookup(){let id=+val('find');let list=Object.entries(stories).filter(([,v])=>v[0]===id);show('<h2>條目 '+id+'</h2>'+list.map(([k,v])=>'<details><summary>'+esc(k.split(':')[1])+' · '+esc(v[5])+'</summary><p>'+esc(v[1])+'</p></details>').join(''))}
function pageView(b=+val('book'),p=+val('page')){let max=[17,40,36,48,36,36,16,36,50,36][b-1];if(!Number.isInteger(p)||p<1||p>max)return warn('此書共 '+max+' 頁。');show('<div>'+ (p>1?btn('上一頁','pageView('+b+','+(p-1)+')'):'')+p+' / '+max+(p<max?btn('下一頁','pageView('+b+','+(p+1)+')'):'')+'</div><img onclick="this.classList.toggle(\'zoomed\')" alt="書頁 '+p+'" src="books/'+String(b).padStart(2,'0')+'_'+String(p).padStart(3,'0')+'.webp">')}
function ending(){let options=[];if(s.missionDone)options.push('使命勝利');if(s.fateDone)options.push(s.missionDone?'史詩勝利':'命運勝利');options.push('旅程告終');show('<h2>結算探險</h2><p>依使命、命運或故事條目指示選擇結局。</p>'+options.map(v=>btn(v,'endGame('+JSON.stringify(v)+')')).join(''))}
function endGame(t){if(t==='使命勝利'&&!s.missionDone||t==='命運勝利'&&!s.fateDone||t==='史詩勝利'&&!(s.fateDone&&s.missionDone))return;s.end=t;s.phase='ended';viewer.close();save()}
function crisis(){let e=stories['story:take:'+String(s.mission).padStart(4,'0')+':01'];return '<section class="panel"><h2>屬性歸零</h2><p>'+esc(e?.[1]||'請閱讀《獲取》故事書中的使命條目。')+'</p>'+btn('依條目作最後一搏','lastStand()')+btn('結算探險','ending()')+'</section>'}
function lastStand(){refresh();for(let i=0;i<10;i++){let d=statNames.indexOf(faces[rng(6)]);if(d>=0)stat(d,1)}if(s.stats.includes(0)){s.phase='ended';s.end='最後一搏未能挽回旅程'}save()}
function go(v){tab=v;notice='';save()}
function render(){let html;if(!s)html=home();else if(s.phase==='ended')html='<section class="hero"><div><small>第 '+s.turn+' 回合</small><h1>'+esc(s.end)+'</h1></div></section>'+btn('開始新的旅程','s=null;tab="探險";save()',true);else if(['mission','escape','crash'].includes(s.phase))html=setup();else html='<div class="group">'+['探險','行囊','手冊'].map(v=>btn(v,'go('+JSON.stringify(v)+')',v===tab)).join('')+'</div><div class="stats">'+statNames.map((v,i)=>'<span>'+v+' '+s.stats[i]+'</span>').join('')+'<span>骰池 '+pool()+'/10</span></div>'+(tab==='手冊'?records():tab==='行囊'?bag():s.stats.includes(0)&&s.phase!=='dice'?crisis():'<div class="play"><section class="panel"><small>第 '+s.turn+' 回合</small><h2>地點 '+pad(s.loc)+'</h2>'+art(s.loc)+'<p class="note">若卡面列有抵達效果，請在行囊結算。</p></section><section class="panel">'+mainTurn()+'</section></div>');app.innerHTML=(notice?'<p role="status">'+esc(notice)+'</p>':'')+html}
render();
